import { isSameIssuer } from '@nao/shared/oidc';
import type { FastifyRequest } from 'fastify';

import type { App } from '../app';
import { getAuth } from '../auth';
import { hasFeature, LICENSE_FEATURES } from '../services/license.service';
import { getOidcIssuer, getOidcProviderId, isOidcConfigured } from '../services/oidc-auth.service';

const LOGIN_PATH = '/login';

/**
 * Identity providers launch an app by redirecting to it with an `iss` query param instead of
 * starting the OAuth flow themselves, so nao starts the flow and sends the browser straight to
 * the provider without ever rendering the login page.
 */
export const ssoRoutes = async (app: App) => {
	app.get('/sso/start', async (request, reply) => {
		const { iss } = request.query as { iss?: string };

		if (!isOidcConfigured() || !(await hasFeature(LICENSE_FEATURES.sso))) {
			return reply.redirect(LOGIN_PATH, 302);
		}
		if (iss && !isSameIssuer(iss, getOidcIssuer())) {
			app.log.warn({ iss }, 'Ignoring identity-provider-initiated sign-in from an unknown issuer');
			return reply.redirect(LOGIN_PATH, 302);
		}

		try {
			const { url, cookies } = await startOidcAuthorization(request);
			if (cookies.length > 0) {
				reply.header('set-cookie', cookies);
			}
			return reply.redirect(url, 302);
		} catch (error) {
			app.log.error(error, 'Failed to start OIDC sign-in');
			return reply.redirect(`${LOGIN_PATH}?error=oidc_start_failed`, 302);
		}
	});
};

/** Delegates to better-auth so state and PKCE cookies are issued exactly as for the login button. */
async function startOidcAuthorization(request: FastifyRequest): Promise<{ url: string; cookies: string[] }> {
	const auth = await getAuth();
	const endpoint = new URL('/api/auth/sign-in/oauth2', `http://${request.headers.host}`);
	const response = await auth.handler(
		new Request(endpoint, {
			method: 'POST',
			headers: { 'content-type': 'application/json' },
			body: JSON.stringify({
				providerId: getOidcProviderId(),
				callbackURL: '/',
				errorCallbackURL: LOGIN_PATH,
			}),
		}),
	);

	const { url } = (await response.json()) as { url?: string };
	if (!response.ok || !url) {
		throw new Error(`better-auth returned no authorization URL (status ${response.status})`);
	}
	return { url, cookies: response.headers.getSetCookie() };
}

